  return padTemplates[footprint] || padTemplates['0402'];
}

/**
 * Parse .cypcb source code into a BoardSnapshot.
 * This is the JavaScript parser used when tree-sitter is not available (WASM mode).
 */
function parseSource(source: string): { snapshot: BoardSnapshot; errors: string[] } {
  const errors: string[] = [];
  const lines = source.split('\n');

  let board: BoardInfo | null = null;
  let currentBoard: BoardInfo | null = null;
  const components: ComponentInfo[] = [];
  const nets: Map<string, NetInfo> = new Map();
  let currentComponent: Partial<ComponentInfo> | null = null;
  let currentNet: { name: string; pins: string[] } | null = null;
  let braceDepth = 0;
  let inBoard = false;
  let inComponent = false;
  let inNet = false;

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum].trim();
    if (!line || line.startsWith('//')) continue;

    // Count braces
    const openBraces = (line.match(/{/g) || []).length;
    const closeBraces = (line.match(/}/g) || []).length;

    // Parse version (ignore)
    if (line.startsWith('version ')) {
      continue;
    }

    // Parse board definition
    const boardMatch = line.match(/^board\s+(\w+)\s*{?$/);
    if (boardMatch) {
      currentBoard = {
        name: boardMatch[1],
        width_nm: 0,
        height_nm: 0,
        layer_count: 2,
      };
      inBoard = true;
      braceDepth += openBraces;
      continue;
    }

    // Parse component definition
    const compMatch = line.match(/^component\s+(\w+)\s+(\w+)\s+"([^"]+)"\s*{?$/);
    if (compMatch) {
      currentComponent = {
        refdes: compMatch[1],
        value: '',
        x_nm: 0,
        y_nm: 0,
        rotation_mdeg: 0,
        footprint: compMatch[3],
        pads: getFootprintPads(compMatch[3]),
      };
      inComponent = true;
      braceDepth += openBraces;
      continue;
    }

    // Parse net definition
    const netMatch = line.match(/^net\s+(\w+)\s*{?$/);
    if (netMatch) {
      currentNet = { name: netMatch[1], pins: [] };
      inNet = true;
      braceDepth += openBraces;
      continue;
    }

    // Parse board properties
    if (inBoard && currentBoard) {
      const sizeMatch = line.match(/^size\s+(\d+(?:\.\d+)?)(mm|mil|inch)\s+x\s+(\d+(?:\.\d+)?)(mm|mil|inch)$/);
      if (sizeMatch) {
        currentBoard.width_nm = parseUnit(parseFloat(sizeMatch[1]), sizeMatch[2]);
        currentBoard.height_nm = parseUnit(parseFloat(sizeMatch[3]), sizeMatch[4]);
      }
      const layersMatch = line.match(/^layers\s+(\d+)$/);
      if (layersMatch) {
        currentBoard.layer_count = parseInt(layersMatch[1], 10);
      }
    }

    // Parse component properties
    if (inComponent && currentComponent) {
      const valueMatch = line.match(/^value\s+"([^"]*)"$/);
      if (valueMatch) {
        currentComponent.value = valueMatch[1];
      }
      const atMatch = line.match(/^at\s+(\d+(?:\.\d+)?)(mm|mil|inch),\s*(\d+(?:\.\d+)?)(mm|mil|inch)(?:\s+rotate\s+(\d+(?:\.\d+)?))?$/);
      if (atMatch) {
        currentComponent.x_nm = parseUnit(parseFloat(atMatch[1]), atMatch[2]);
        currentComponent.y_nm = parseUnit(parseFloat(atMatch[3]), atMatch[4]);
        if (atMatch[5]) {
          currentComponent.rotation_mdeg = Math.round(parseFloat(atMatch[5]) * 1000);
        }
      }
    }

    // Parse net pins
    if (inNet && currentNet) {
      const pinMatch = line.match(/^(\w+)\.(\w+)$/);
      if (pinMatch) {
        currentNet.pins.push(`${pinMatch[1]}.${pinMatch[2]}`);
      }
    }

    // Handle closing braces
    if (closeBraces > 0) {
      braceDepth -= closeBraces;

      if (braceDepth <= 0) {
        if (inBoard && currentBoard) {
          board = currentBoard;
          currentBoard = null;
          inBoard = false;
        }
        if (inComponent && currentComponent) {
          components.push(currentComponent as ComponentInfo);
          currentComponent = null;
          inComponent = false;
        }
        if (inNet && currentNet) {
          const connections: PinRef[] = currentNet.pins.map(pin => {
            const [component, pinNum] = pin.split('.');
            return { component, pin: pinNum };
          });
          nets.set(currentNet.name, {
            name: currentNet.name,
            id: nets.size,
            connections,
          });
          currentNet = null;
          inNet = false;
        }
        braceDepth = 0;
      }
    }

    braceDepth += openBraces;
  }

  return {
    snapshot: { board, components, nets: Array.from(nets.values()), violations: [], traces: [], vias: [], ratsnest: [] },
    errors,
  };
}

/**
 * Parse FreeRouting .ses (session) file to extract routing results.
 * Returns traces and vias that can be added to a BoardSnapshot.
 */
export function parseSesFile(sesContent: string): { traces: BoardSnapshot['traces']; vias: BoardSnapshot['vias'] } {
  const traces: BoardSnapshot['traces'] = [];
  const vias: BoardSnapshot['vias'] = [];

  // Default resolution: mil 10 = 1/10 mil = 2540 nm
  let resolution = 2540; // nm per unit

  // Parse resolution from routes section
  const resMatch = sesContent.match(/\(routes[\s\S]*?\(resolution\s+(\w+)\s+(\d+)\)/);
  if (resMatch) {
    const unit = resMatch[1];
    const divisor = parseInt(resMatch[2], 10);
    if (unit === 'mil') {
      resolution = Math.round(25400 / divisor); // 1 mil = 25400 nm
    } else if (unit === 'mm') {
      resolution = Math.round(1_000_000 / divisor);
    }
  }
  console.log('[SES Parser] Resolution:', resolution, 'nm per unit');

  // Find network_out content
  const networkOutStart = sesContent.indexOf('(network_out');
  if (networkOutStart === -1) {
    console.log('[SES Parser] No network_out section found');
    return { traces, vias };
  }
  const networkSection = sesContent.slice(networkOutStart);

  // Find net blocks by counting parentheses (more reliable than regex)
  let pos = 0;
  while (true) {
    const netStart = networkSection.indexOf('(net ', pos);
    if (netStart === -1) break;

    // Find net name
    const nameMatch = networkSection.slice(netStart).match(/\(net\s+(\w+)/);
    if (!nameMatch) break;
    const netName = nameMatch[1];

    // Find where this net ends by counting parentheses
    let depth = 0;
    let netEnd = netStart;
    for (let i = netStart; i < networkSection.length; i++) {
      if (networkSection[i] === '(') depth++;
      if (networkSection[i] === ')') depth--;
      if (depth === 0) {
        netEnd = i + 1;
        break;
      }
    }

    const netContent = networkSection.slice(netStart, netEnd);
    pos = netEnd;

    // Find all wire paths in this net
    const wirePathRegex = /\(path\s+(\S+)\s+(\d+)\s+([\d\s\-]+)\)/g;
    let pathMatch;

    while ((pathMatch = wirePathRegex.exec(netContent)) !== null) {
      const layerStr = pathMatch[1];
      const width = parseInt(pathMatch[2], 10) * resolution;
      const coordsStr = pathMatch[3].trim();
      const coords = coordsStr.split(/\s+/).map(s => parseInt(s, 10));

      // Convert layer name (F.Cu -> Top, B.Cu -> Bottom)
      const layer = layerStr === 'B.Cu' ? 'Bottom' : 'Top';

      // Create segments from coordinate pairs
      const segments: { start_x: number; start_y: number; end_x: number; end_y: number }[] = [];
      for (let i = 0; i < coords.length - 2; i += 2) {
        segments.push({
          start_x: coords[i] * resolution,
          start_y: coords[i + 1] * resolution,
          end_x: coords[i + 2] * resolution,
          end_y: coords[i + 3] * resolution,
        });
      }

      if (segments.length > 0) {
        traces.push({
          id: traces.length,
          segments,
          width,
          layer,
          net_name: netName,
          locked: false,
        });
      }
    }

    // Find vias in this net
    const viaRegex = /\(via\s+\w+\s+(\d+)\s+(\d+)\)/g;
    let viaMatch;
    while ((viaMatch = viaRegex.exec(netContent)) !== null) {
      vias.push({
        id: vias.length,
        x: parseInt(viaMatch[1], 10) * resolution,
        y: parseInt(viaMatch[2], 10) * resolution,
        drill: 300_000,
        outer_diameter: 600_000,
        net_name: netName,
      });
    }
  }

  console.log('[SES Parser] Parsed', traces.length, 'traces,', vias.length, 'vias');
  return { traces, vias };
}

// ============================================================================
// Geometry utilities (used by MockPcbEngine hit-testing and DRC)
// ============================================================================

/**
 * Shortest distance from point (px,py) to line segment (ax,ay)-(bx,by).
 */
function pointToSegmentDistance(
  px: number, py: number,
  ax: number, ay: number,
  bx: number, by: number,
): number {
  const dx = bx - ax;
  const dy = by - ay;
  const lenSq = dx * dx + dy * dy;
  if (lenSq === 0) {
    const ex = px - ax;
    const ey = py - ay;
    return Math.sqrt(ex * ex + ey * ey);
  }
  let t = ((px - ax) * dx + (py - ay) * dy) / lenSq;
  t = Math.max(0, Math.min(1, t));
  const cx = ax + t * dx;
  const cy = ay + t * dy;
  const ex = px - cx;
  const ey = py - cy;
  return Math.sqrt(ex * ex + ey * ey);
}

/**
 * Approximate minimum distance between two line segments.
 * Tests endpoints of each segment against the other segment.
 */
function segmentToSegmentDistance(
  s1: TraceSegmentInfo,
  s2: TraceSegmentInfo,
): number {
  // Sample several points: endpoints + midpoints, take minimum
  const d1 = pointToSegmentDistance(s1.start_x, s1.start_y, s2.start_x, s2.start_y, s2.end_x, s2.end_y);
  const d2 = pointToSegmentDistance(s1.end_x, s1.end_y, s2.start_x, s2.start_y, s2.end_x, s2.end_y);
  const d3 = pointToSegmentDistance(s2.start_x, s2.start_y, s1.start_x, s1.start_y, s1.end_x, s1.end_y);
  const d4 = pointToSegmentDistance(s2.end_x, s2.end_y, s1.start_x, s1.start_y, s1.end_x, s1.end_y);
  return Math.min(d1, d2, d3, d4);
}

// ============================================================================
// WASM Engine Adapter
// ============================================================================

/**
 * Adapter that wraps the raw WASM PcbEngine and provides the load_source() method.
 *
 * The WASM engine doesn't include tree-sitter, so parsing is done in JavaScript.
 * This adapter parses the source, then calls load_snapshot() on the WASM engine.
 * Query operations use the WASM engine's spatial index for efficiency.
 */
class WasmPcbEngineAdapter implements PcbEngine {
  private wasmEngine: WasmPcbEngine;
  private cachedSnapshot: BoardSnapshot | null = null;

  constructor(wasmEngine: WasmPcbEngine) {
    this.wasmEngine = wasmEngine;
  }

  load_source(source: string): string {
    // Parse in JavaScript
    const { snapshot, errors } = parseSource(source);

    // Cache snapshot (traces/vias/ratsnest will be populated by load_routes)
    this.cachedSnapshot = snapshot;

    // Store snapshot and load into WASM engine for queries
    const wasmError = this.wasmEngine.load_snapshot(snapshot);
    if (wasmError) {
      errors.push(wasmError);
    }

    return errors.join('\n');
  }

  load_routes(sesContent: string): void {
    if (!this.cachedSnapshot) return;

    // Parse .ses file and extract routes
    const { traces, vias } = parseSesFile(sesContent);

    // Replace traces and vias in cached snapshot
    this.cachedSnapshot.traces = traces;
    this.cachedSnapshot.vias = vias;

    // Build set of routed connections (net + pin)
    const routedPins = new Set<string>();
    for (const trace of traces) {
      if (trace.net_name) {
        // For each net, we consider all pins in that net as "connected" if there are traces
        const net = this.cachedSnapshot.nets.find(n => n.name === trace.net_name);
        if (net) {
          for (const conn of net.connections) {
            routedPins.add(`${conn.component}.${conn.pin}`);
          }
        }
      }
    }

    // Regenerate ratsnest only for unrouted connections
    this.cachedSnapshot.ratsnest = [];
    for (const net of this.cachedSnapshot.nets) {
      if (net.connections.length < 2) continue;

      // Check if this net has any traces
      const hasTraces = traces.some(t => t.net_name === net.name);
      if (hasTraces) continue; // Skip routed nets

      // Get pin positions for unrouted net
      const positions: { x: number; y: number }[] = [];
      for (const conn of net.connections) {
        const comp = this.cachedSnapshot.components.find(c => c.refdes === conn.component);
        if (comp) {
          const pad = comp.pads.find(p => p.number === conn.pin);
          positions.push({
            x: comp.x_nm + (pad?.x_nm ?? 0),
            y: comp.y_nm + (pad?.y_nm ?? 0),
          });
        }
      }

      // Create star-topology ratsnest
      if (positions.length >= 2) {
        for (let i = 1; i < positions.length; i++) {
          this.cachedSnapshot.ratsnest.push({
            start_x: positions[0].x,
            start_y: positions[0].y,
            end_x: positions[i].x,
            end_y: positions[i].y,
            net_name: net.name,
          });
        }
      }
    }
  }

  get_snapshot(): BoardSnapshot {
    // Return cached snapshot with traces/ratsnest that we added in JS
    // The WASM engine's get_snapshot() would have empty traces since
    // we only populated components/board, not Trace entities
    if (this.cachedSnapshot) {
      // Get DRC violations from WASM (computed in Rust)
      const wasmSnapshot = this.wasmEngine.get_snapshot();
      return {
        ...this.cachedSnapshot,
        violations: wasmSnapshot.violations || [],
      };
    }
    return this.wasmEngine.get_snapshot();
  }

  query_point(x_nm: number, y_nm: number): string[] {
    // Use WASM spatial index for efficient queries
    // The WASM engine rebuilds the spatial index in populate_from_snapshot()
    return this.wasmEngine.query_point(BigInt(x_nm), BigInt(y_nm));
  }

  add_trace(net_name: string, layer: string, width_nm: number, segments: number[]): number {
    const id = this.wasmEngine.add_trace_json(net_name, layer, BigInt(width_nm), JSON.stringify(segments));
    // Invalidate cached snapshot so next get_snapshot() picks up the new trace
    this.cachedSnapshot = null;
    return id;
  }

  remove_trace(trace_id: number): boolean {
    const removed = this.wasmEngine.remove_trace(trace_id);
    if (removed) {
      this.cachedSnapshot = null;
    }
    return removed;
  }

  get_trace_at_point(x_nm: number, y_nm: number, tolerance_nm: number): number {
    return this.wasmEngine.get_trace_at_point(BigInt(x_nm), BigInt(y_nm), BigInt(tolerance_nm));
  }

  run_drc_incremental(): number {
    return this.wasmEngine.run_drc_incremental();
  }

  trace_count(): number {
    return this.wasmEngine.trace_count();
  }

  free(): void {
    this.wasmEngine.free();
  }
}

// ============================================================================
// Mock Engine (fallback when WASM is unavailable)
// ============================================================================

/**
 * Mock PCB engine for development/testing without WASM.
 * Uses the same JavaScript parser as the WASM adapter.
 */
class MockPcbEngine implements PcbEngine {
  private snapshot: BoardSnapshot = { board: null, components: [], nets: [], violations: [], traces: [], vias: [], ratsnest: [] };
  /** Next mock entity ID counter */
  private nextEntityId = 1000;

  load_source(source: string): string {
    const { snapshot, errors } = parseSource(source);
    this.snapshot = snapshot;
    return errors.join('\n');
  }

  load_routes(sesContent: string): void {
    // Parse .ses file and extract routes
    const { traces, vias } = parseSesFile(sesContent);

    // Replace traces and vias
    this.snapshot.traces = traces;
    this.snapshot.vias = vias;

    // Regenerate ratsnest only for unrouted nets
    this.snapshot.ratsnest = [];
    for (const net of this.snapshot.nets) {
      if (net.connections.length < 2) continue;

      // Skip nets that have traces
      const hasTraces = traces.some(t => t.net_name === net.name);
      if (hasTraces) continue;

      // Get pin positions for unrouted net
      const positions: { x: number; y: number }[] = [];
      for (const conn of net.connections) {
        const comp = this.snapshot.components.find(c => c.refdes === conn.component);
        if (comp) {
          const pad = comp.pads.find(p => p.number === conn.pin);
          positions.push({
            x: comp.x_nm + (pad?.x_nm ?? 0),
            y: comp.y_nm + (pad?.y_nm ?? 0),
          });
        }
      }

      // Create star-topology ratsnest
      if (positions.length >= 2) {
        for (let i = 1; i < positions.length; i++) {
          this.snapshot.ratsnest.push({
            start_x: positions[0].x,
            start_y: positions[0].y,
            end_x: positions[i].x,
            end_y: positions[i].y,
            net_name: net.name,
          });
        }
      }
    }
  }

  get_snapshot(): BoardSnapshot {
    return this.snapshot;
  }

  query_point(x_nm: number, y_nm: number): string[] {
    const result: string[] = [];

    for (const comp of this.snapshot.components) {
      // Check if point is within component bounds (simplified)
      const compWidth = 2_000_000; // 2mm default
      const compHeight = 1_000_000; // 1mm default

      if (x_nm >= comp.x_nm - compWidth / 2 &&
          x_nm <= comp.x_nm + compWidth / 2 &&
          y_nm >= comp.y_nm - compHeight / 2 &&
          y_nm <= comp.y_nm + compHeight / 2) {
        result.push(comp.refdes);
      }
    }

    return result;
  }

  // -- Trace mutation API (MockPcbEngine) --

  add_trace(net_name: string, layer: string, width_nm: number, segments: number[]): number {
    // Validate inputs
    if (segments.length < 4 || segments.length % 4 !== 0) {
      return 0xFFFFFFFF;
    }
    const validLayers = ['Top', 'TopCopper', 'Bottom', 'BottomCopper'];
    const isInner = /^Inner\d+$/.test(layer);
    if (!validLayers.includes(layer) && !isInner) {
      return 0xFFFFFFFF;
    }

    const id = this.nextEntityId++;
    const traceSegments: TraceSegmentInfo[] = [];
    for (let i = 0; i < segments.length; i += 4) {
      traceSegments.push({
        start_x: segments[i],
        start_y: segments[i + 1],
        end_x: segments[i + 2],
        end_y: segments[i + 3],
      });
    }

    // Normalize layer name
    const normalizedLayer = layer === 'TopCopper' ? 'Top' : layer === 'BottomCopper' ? 'Bottom' : layer;

    this.snapshot.traces.push({
      id,
      segments: traceSegments,
      width: width_nm,
      layer: normalizedLayer,
      net_name,
      locked: false,
    });

    console.log(`[MockEngine] add_trace: net=${net_name} layer=${normalizedLayer} id=${id} segs=${traceSegments.length}`);
    return id;
  }

  remove_trace(trace_id: number): boolean {
    const idx = this.snapshot.traces.findIndex(t => t.id === trace_id);
    if (idx === -1) return false;
    this.snapshot.traces.splice(idx, 1);
    console.log(`[MockEngine] remove_trace: id=${trace_id}`);
    return true;
  }

  get_trace_at_point(x_nm: number, y_nm: number, tolerance_nm: number): number {
    let bestId = 0xFFFFFFFF;
    let bestDist = Infinity;

    for (const trace of this.snapshot.traces) {
      const halfWidth = trace.width / 2;
      for (const seg of trace.segments) {
        const dist = pointToSegmentDistance(
          x_nm, y_nm,
          seg.start_x, seg.start_y,
          seg.end_x, seg.end_y,
        );
        if (dist <= halfWidth + tolerance_nm && dist < bestDist) {
          bestDist = dist;
          bestId = trace.id;
        }
      }
    }

    return bestId;
  }

  run_drc_incremental(): number {
    // Mock: simple clearance check between traces
    // Real DRC is in Rust — this just provides a realistic interface
    const violations: ViolationInfo[] = [];
    const MIN_CLEARANCE = 150_000; // 0.15mm in nm

    for (let i = 0; i < this.snapshot.traces.length; i++) {
      for (let j = i + 1; j < this.snapshot.traces.length; j++) {
        const t1 = this.snapshot.traces[i];
        const t2 = this.snapshot.traces[j];
        if (t1.net_name === t2.net_name) continue; // Same net is fine
        if (t1.layer !== t2.layer) continue; // Different layers don't interact

        for (const s1 of t1.segments) {
          for (const s2 of t2.segments) {
            const dist = segmentToSegmentDistance(s1, s2);
            const required = t1.width / 2 + t2.width / 2 + MIN_CLEARANCE;
            if (dist < required) {
              const mx = (s1.start_x + s1.end_x + s2.start_x + s2.end_x) / 4;
              const my = (s1.start_y + s1.end_y + s2.start_y + s2.end_y) / 4;
              violations.push({
                kind: 'clearance',
                x_nm: mx,
                y_nm: my,
                message: `Clearance violation between ${t1.net_name} and ${t2.net_name}: ${(dist / 1_000_000).toFixed(2)}mm < ${(required / 1_000_000).toFixed(2)}mm required`,
              });
            }
          }
        }
      }
    }

    this.snapshot.violations = violations;
    console.log(`[MockEngine] run_drc_incremental: ${violations.length} violations`);
    return violations.length;
  }

  trace_count(): number {
    return this.snapshot.traces.length;
  }
}

// ============================================================================
// Module loading
// ============================================================================

/**
 * Load the WASM module and return the PCB engine instance.
 * Falls back to mock implementation if WASM is not available.
 *
 * @returns The PCB engine instance
 */
export async function loadWasm(): Promise<PcbEngine> {
  if (engineInstance) {
    return engineInstance;
  }

  // Try to load the real WASM module first
  try {
    // Direct import - Vite will handle bundling with vite-plugin-wasm
    const wasm = await import('../pkg/cypcb_render.js');
    await wasm.default();
    wasmModule = wasm;

    // Wrap the WASM engine with our adapter that provides load_source()
    const rawEngine = new wasm.PcbEngine() as unknown as WasmPcbEngine;
    engineInstance = new WasmPcbEngineAdapter(rawEngine);
    console.log('WASM module loaded successfully');
    return engineInstance;
  } catch (e) {
    console.log('WASM not available, using mock:', e);
  }

  // Fallback to MockPcbEngine when:
  // - Development without WASM build
  // - Environments where WASM fails to load
  // - Testing without the Rust backend
  console.log('Using MockPcbEngine (WASM fallback)');
  engineInstance = new MockPcbEngine();
  return engineInstance;
}

/**
 * Get the current engine instance (if loaded)
 */
export function getEngine(): PcbEngine | null {
  return engineInstance;
}

/**
 * Helper to load source and get snapshot in one call
 */
export function loadAndSnapshot(source: string): { snapshot: BoardSnapshot; errors: string } | null {
  if (!engineInstance) return null;

  const errors = engineInstance.load_source(source);
  const snapshot = engineInstance.get_snapshot();

  return { snapshot, errors };
}

/**
 * Check if the engine is using the real WASM implementation
 */
export function isWasmLoaded(): boolean {
  return wasmModule !== null;
}

//! BoardWorld - High-level API for PCB board entities.
//!
//! Provides a clean wrapper around bevy_ecs::World with PCB-specific
//! operations for creating boards, spawning components, and querying.
//!
//! # Example
//!
//! ```
//! use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
//! use cypcb_core::Nm;
//!
//! // Create a new board world
//! let mut world = BoardWorld::new();
//!
//! // Set up the board
//! let board = world.set_board("MyBoard".to_string(), (Nm::from_mm(100.0), Nm::from_mm(80.0)), 4);
//!
//! // Intern net names
//! let vcc = world.intern_net("VCC");
//! let gnd = world.intern_net("GND");
//!
//! // Spawn components
//! let r1 = world.spawn_component(
//!     RefDes::new("R1"),
//!     Value::new("10k"),
//!     Position::from_mm(10.0, 20.0),
//!     Rotation::ZERO,
//!     FootprintRef::new("0402"),
//!     NetConnections::new(),
//! );
//!
//! // Query the world
//! assert_eq!(world.component_count(), 1);
//! ```

use bevy_ecs::prelude::*;

use cypcb_core::{Nm, Point, Rect};

use crate::components::*;
use crate::registry::NetRegistry;
use crate::spatial::{SpatialEntry, SpatialIndex};

/// High-level wrapper around bevy_ecs::World for PCB board operations.
///
/// BoardWorld provides a clean, type-safe API for:
/// - Creating and configuring the board
/// - Spawning component entities
/// - Interning net names
/// - Spatial queries
/// - Direct ECS access when needed
///
/// # Architecture
///
/// Internally uses bevy_ecs::World with two resources:
/// - [`NetRegistry`]: For interning net names to integer IDs
/// - [`SpatialIndex`]: For efficient region-based queries
///
/// # Example
///
/// ```
/// use cypcb_world::BoardWorld;
/// use cypcb_core::Nm;
///
/// let mut world = BoardWorld::new();
///
/// // Create a 100x80mm 4-layer board
/// world.set_board("MyPCB".to_string(), (Nm::from_mm(100.0), Nm::from_mm(80.0)), 4);
///
/// // Get board info
/// if let Some((size, layers)) = world.board_info() {
///     println!("Board: {}x{}, {} layers", size.width, size.height, layers.count);
/// }
/// ```
pub struct BoardWorld {
    /// The underlying bevy_ecs World.
    world: World,
    /// Entity ID of the board (if set).
    board_entity: Option<Entity>,
}

impl BoardWorld {
    /// Create a new empty BoardWorld.
    ///
    /// Initializes the ECS world with:
    /// - Empty [`SpatialIndex`] resource
    /// - Empty [`NetRegistry`] resource
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let world = BoardWorld::new();
    /// assert!(world.is_empty());
    /// ```
    pub fn new() -> Self {
        let mut world = World::new();
        world.insert_resource(SpatialIndex::new());
        world.insert_resource(NetRegistry::new());
        BoardWorld {
            world,
            board_entity: None,
        }
    }

    // ========================================================================
    // Board Management
    // ========================================================================

    /// Set the board properties, creating or updating the board entity.
    ///
    /// There can only be one board entity. Calling this multiple times
    /// will update the existing board entity.
    ///
    /// # Arguments
    ///
    /// * `name` - Board name/identifier
    /// * `size` - Board dimensions as (width, height) in nanometers
    /// * `layers` - Number of copper layers (2-32)
    ///
    /// # Returns
    ///
    /// The board entity ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    /// use cypcb_core::Nm;
    ///
    /// let mut world = BoardWorld::new();
    /// let board = world.set_board(
    ///     "TestBoard".to_string(),
    ///     (Nm::from_mm(100.0), Nm::from_mm(80.0)),
    ///     4,
    /// );
    /// ```
    pub fn set_board(&mut self, name: String, size: (Nm, Nm), layers: u8) -> Entity {
        let board_size = BoardSize::new(size.0, size.1);
        let layer_stack = LayerStack::new(layers);
        let name_component = crate::components::metadata::Name(name);

        if let Some(entity) = self.board_entity {
            // Update existing board
            let mut entity_mut = self.world.entity_mut(entity);
            entity_mut.insert((Board, board_size, layer_stack, name_component));
            entity
        } else {
            // Create new board
            let entity = self
                .world
                .spawn((Board, board_size, layer_stack, name_component))
                .id();
            self.board_entity = Some(entity);
            entity
        }
    }

    /// Get the board entity ID if one has been set.
    pub fn board_entity(&self) -> Option<Entity> {
        self.board_entity
    }

    /// Get board size and layer stack if a board has been set.
    ///
    /// # Returns
    ///
    /// Tuple of (BoardSize, LayerStack) if board exists, None otherwise.
    pub fn board_info(&self) -> Option<(BoardSize, LayerStack)> {
        let entity = self.board_entity?;
        let size = self.world.get::<BoardSize>(entity)?;
        let layers = self.world.get::<LayerStack>(entity)?;
        Some((*size, *layers))
    }

    /// Get the board name if one has been set.
    pub fn board_name(&self) -> Option<&str> {
        let entity = self.board_entity?;
        self.world
            .get::<crate::components::metadata::Name>(entity)
            .map(|n| n.0.as_str())
    }

    // ========================================================================
    // Component Spawning
    // ========================================================================

    /// Spawn a new component entity.
    ///
    /// # Arguments
    ///
    /// * `refdes` - Reference designator (R1, C1, U1, etc.)
    /// * `value` - Component value (10k, 100nF, etc.)
    /// * `position` - Position on board
    /// * `rotation` - Rotation angle
    /// * `footprint` - Footprint reference
    /// * `nets` - Net connections for each pin
    ///
    /// # Returns
    ///
    /// The spawned entity ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    /// ```
    pub fn spawn_component(
        &mut self,
        refdes: RefDes,
        value: Value,
        position: Position,
        rotation: Rotation,
        footprint: FootprintRef,
        nets: NetConnections,
    ) -> Entity {
        self.world
            .spawn((refdes, value, position, rotation, footprint, nets))
            .id()
    }

    /// Spawn a component with a source span for error reporting.
    ///
    /// Same as [`spawn_component`](Self::spawn_component) but also attaches
    /// a [`SourceSpan`] for linking back to source file locations.
    pub fn spawn_component_with_span(
        &mut self,
        refdes: RefDes,
        value: Value,
        position: Position,
        rotation: Rotation,
        footprint: FootprintRef,
        nets: NetConnections,
        span: SourceSpan,
    ) -> Entity {
        self.world
            .spawn((refdes, value, position, rotation, footprint, nets, span))
            .id()
    }

    /// Spawn an entity with arbitrary components.
    ///
    /// Use this for custom entity types not covered by [`spawn_component`](Self::spawn_component).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Position};
    ///
    /// let mut world = BoardWorld::new();
    /// let entity = world.spawn_entity((
    ///     RefDes::new("J1"),
    ///     Position::from_mm(5.0, 5.0),
    /// ));
    /// ```
    pub fn spawn_entity<B: Bundle>(&mut self, bundle: B) -> Entity {
        self.world.spawn(bundle).id()
    }

    // ========================================================================
    // Net Registry
    // ========================================================================

    /// Intern a net name, returning its unique NetId.
    ///
    /// If the name has already been interned, returns the existing ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let mut world = BoardWorld::new();
    /// let vcc = world.intern_net("VCC");
    /// let vcc2 = world.intern_net("VCC");
    /// assert_eq!(vcc, vcc2); // Same ID
    /// ```
    pub fn intern_net(&mut self, name: &str) -> NetId {
        self.world.resource_mut::<NetRegistry>().intern(name)
    }

    /// Get the name for a NetId.
    ///
    /// Returns None if the ID is invalid.
    pub fn net_name(&self, id: NetId) -> Option<&str> {
        self.world.resource::<NetRegistry>().name(id)
    }

    /// Look up a NetId by name without interning.
    ///
    /// Returns None if the name has not been interned.
    pub fn get_net(&self, name: &str) -> Option<NetId> {
        self.world.resource::<NetRegistry>().get(name)
    }

    /// Get the number of interned nets.
    pub fn net_count(&self) -> usize {
        self.world.resource::<NetRegistry>().len()
    }

    /// Iterate over all interned nets.
    pub fn nets(&self) -> impl Iterator<Item = (NetId, &str)> {
        self.world.resource::<NetRegistry>().iter()
    }

    // ========================================================================
    // Spatial Index
    // ========================================================================

    /// Get a reference to the spatial index.
    ///
    /// Use this for direct spatial queries, iteration, or DRC checks.
    ///
    /// # Note
    ///
    /// The spatial index must be rebuilt after component changes
    /// using [`rebuild_spatial_index`](Self::rebuild_spatial_index).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let world = BoardWorld::new();
    /// let spatial = world.spatial();
    /// assert!(spatial.is_empty());
    /// ```
    pub fn spatial(&self) -> &SpatialIndex {
        self.world.resource::<SpatialIndex>()
    }

    /// Rebuild the spatial index from current component positions.
    ///
    /// Call this after modifying component positions or spawning
    /// components to update the spatial index for efficient queries.
    ///
    /// # Arguments
    ///
    /// * `footprint_bounds` - Function to get bounds for a footprint name.
    ///   Used to calculate entity bounding boxes.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    /// use cypcb_core::{Nm, Rect, Point};
    ///
    /// let mut world = BoardWorld::new();
    /// // ... spawn components ...
    ///
    /// // Rebuild with simple bounds
    /// world.rebuild_spatial_index(|_| Rect::from_center_size(
    ///     Point::ORIGIN,
    ///     (Nm::from_mm(1.0), Nm::from_mm(1.0)),
    /// ));
    /// ```
    pub fn rebuild_spatial_index<F>(&mut self, footprint_bounds: F)
    where
        F: Fn(&str) -> Rect,
    {
        let mut entries = Vec::new();

        // Query all positioned entities with footprints
        let mut query = self
            .world
            .query::<(Entity, &Position, &FootprintRef)>();

        for (entity, position, footprint) in query.iter(&self.world) {
            let bounds = footprint_bounds(footprint.as_str());
            let pos = position.0;

            // Translate bounds by position
            let min = Point::new(
                Nm(pos.x.0 + bounds.min.x.0),
                Nm(pos.y.0 + bounds.min.y.0),
            );
            let max = Point::new(
                Nm(pos.x.0 + bounds.max.x.0),
                Nm(pos.y.0 + bounds.max.y.0),
            );

            // Default to all layers for now (could be refined with pad layer info)
            let layer_mask = 0xFFFFFFFF;

            entries.push(SpatialEntry::new(entity, min, max, layer_mask));
        }

        self.world.resource_mut::<SpatialIndex>().rebuild(entries);
    }

    /// Rebuild the spatial index from current components, traces, and vias.
    ///
    /// Extends [`rebuild_spatial_index`](Self::rebuild_spatial_index) by also indexing:
    /// - **Trace segments**: Each segment gets an AABB expanded by half the trace width.
    /// - **Vias**: Indexed as circular AABBs using `outer_diameter / 2` as the radius.
    ///
    /// Layer masks are derived from `Layer::to_copper_mask()`.
    ///
    /// # Arguments
    ///
    /// * `footprint_bounds` - Function to get bounds for a footprint name (for components).
    pub fn rebuild_spatial_index_with_traces<F>(&mut self, footprint_bounds: F)
    where
        F: Fn(&str) -> Rect,
    {
        let mut entries = Vec::new();

        // Index components (same as rebuild_spatial_index)
        {
            let mut query = self.world.query::<(Entity, &Position, &FootprintRef)>();
            for (entity, position, footprint) in query.iter(&self.world) {
                let bounds = footprint_bounds(footprint.as_str());
                let pos = position.0;
                let min = Point::new(
                    Nm(pos.x.0 + bounds.min.x.0),
                    Nm(pos.y.0 + bounds.min.y.0),
                );
                let max = Point::new(
                    Nm(pos.x.0 + bounds.max.x.0),
                    Nm(pos.y.0 + bounds.max.y.0),
                );
                let layer_mask = 0xFFFFFFFF;
                entries.push(SpatialEntry::new(entity, min, max, layer_mask));
            }
        }

        // Index trace segments
        {
            let mut query = self.world.query::<(Entity, &crate::components::trace::Trace)>();
            for (entity, trace) in query.iter(&self.world) {
                let half_width = trace.width.0 / 2;
                let layer_mask = trace.layer.to_copper_mask();
                for seg in &trace.segments {
                    let min_x = seg.start.x.0.min(seg.end.x.0) - half_width;
                    let min_y = seg.start.y.0.min(seg.end.y.0) - half_width;
                    let max_x = seg.start.x.0.max(seg.end.x.0) + half_width;
                    let max_y = seg.start.y.0.max(seg.end.y.0) + half_width;
                    entries.push(SpatialEntry::from_raw(
                        entity, min_x, min_y, max_x, max_y, layer_mask,
                    ));
                }
            }
        }

        // Index vias
        {
            let mut query = self.world.query::<(Entity, &crate::components::trace::Via)>();
            for (entity, via) in query.iter(&self.world) {
                let radius = via.outer_diameter.0 / 2;
                let cx = via.position.x.0;
                let cy = via.position.y.0;
                // Via spans from start_layer to end_layer — use both masks
                let layer_mask = via.start_layer.to_copper_mask()
                    | via.end_layer.to_copper_mask();
                entries.push(SpatialEntry::from_raw(
                    entity,
                    cx - radius, cy - radius,
                    cx + radius, cy + radius,
                    layer_mask,
                ));
            }
        }

        self.world.resource_mut::<SpatialIndex>().rebuild(entries);
    }

    /// Query entities in a rectangular region.
    ///
    /// Returns all entities whose bounding boxes intersect the given bounds.
    ///
    /// # Note
    ///
    /// The spatial index must be rebuilt after component changes
    /// using [`rebuild_spatial_index`](Self::rebuild_spatial_index).
    pub fn query_region(&self, bounds: Rect) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_region(bounds.min, bounds.max)
            .collect()
    }

    /// Query entities at a specific point.
    ///
    /// Returns all entities whose bounding boxes contain the point.
    pub fn query_point(&self, point: Point) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_point(point)
            .collect()
    }

    /// Query entities in a region, filtered by layer.
    ///
    /// # Arguments
    ///
    /// * `bounds` - The query region
    /// * `layer_mask` - Bit mask of layers to include
    pub fn query_region_on_layers(&self, bounds: Rect, layer_mask: u32) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_region_on_layers(bounds.min, bounds.max, layer_mask)
            .collect()
    }

    // ========================================================================
    // Entity Queries
    // ========================================================================

    /// Get the number of component entities (excluding board).
    pub fn component_count(&mut self) -> usize {
        let mut query = self.world.query::<&RefDes>();
        query.iter(&self.world).count()
    }

    /// Check if the world is empty (no entities).
    pub fn is_empty(&self) -> bool {
        self.world.entities().len() == 0
    }

    /// Get a component from an entity.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    ///
    /// let refdes = world.get::<RefDes>(r1);
    /// assert_eq!(refdes.map(|r| r.as_str()), Some("R1"));
    /// ```
    pub fn get<T: Component>(&self, entity: Entity) -> Option<&T> {
        self.world.get::<T>(entity)
    }

    /// Get a mutable reference to a component.
    pub fn get_mut<T: Component>(&mut self, entity: Entity) -> Option<Mut<'_, T>> {
        self.world.get_mut::<T>(entity)
    }

    /// Check if an entity has a specific component.
    pub fn has<T: Component>(&self, entity: Entity) -> bool {
        self.world.get::<T>(entity).is_some()
    }

    /// Find an entity by its reference designator.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    ///
    /// assert_eq!(world.find_by_refdes("R1"), Some(r1));
    /// assert_eq!(world.find_by_refdes("R2"), None);
    /// ```
    pub fn find_by_refdes(&mut self, refdes: &str) -> Option<Entity> {
        let mut query = self.world.query::<(Entity, &RefDes)>();
        query
            .iter(&self.world)
            .find(|(_, r)| r.as_str() == refdes)
            .map(|(e, _)| e)
    }

    /// Iterate over all components (entities with RefDes).
    ///
    /// Returns a vector of (Entity, RefDes clone, Position clone) tuples.
    /// Uses clones to avoid lifetime issues with the query.
    pub fn components(&mut self) -> Vec<(Entity, RefDes, Position)> {
        let mut query = self.world.query::<(Entity, &RefDes, &Position)>();
        query
            .iter(&self.world)
            .map(|(e, r, p)| (e, r.clone(), *p))
            .collect()
    }

    /// Iterate over all zones.
    ///
    /// Returns a vector of (Entity, Zone clone) tuples.
    /// Uses clones to avoid lifetime issues with the query.
    pub fn zones(&mut self) -> Vec<(Entity, Zone)> {
        let mut query = self.world.query::<(Entity, &Zone)>();
        query
            .iter(&self.world)
            .map(|(e, z)| (e, z.clone()))
            .collect()
    }

    // ========================================================================
    // Direct ECS Access
    // ========================================================================

    /// Get direct access to the underlying bevy_ecs World.
    ///
    /// Use this for advanced queries not covered by the BoardWorld API.
    pub fn ecs(&self) -> &World {
        &self.world
    }

    /// Get mutable access to the underlying bevy_ecs World.
    ///
    /// Use this for advanced operations not covered by the BoardWorld API.
    pub fn ecs_mut(&mut self) -> &mut World {
        &mut self.world
    }

    // ========================================================================
    // Serialization Helpers
    // ========================================================================

    /// Clear all entities and reset resources.
    pub fn clear(&mut self) {
        self.world.clear_entities();
        self.world.insert_resource(SpatialIndex::new());
        self.world.insert_resource(NetRegistry::new());
        self.board_entity = None;
    }
}

impl Default for BoardWorld {
    fn default() -> Self {
        Self::new()
    }
}

